// Package ratelimit implements a concurrency-safe token-bucket rate limiter.
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// RealClock returns a Clock backed by the system time.
func RealClock() Clock { return realClock{} }

// Limiter is a concurrency-safe token-bucket rate limiter.
// The bucket starts full and refills at Rate tokens per second, up to Burst.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	last     time.Time
	burst    int
	rate     float64 // tokens per second
	clock    Clock
}

// New creates a Limiter with the given burst capacity and refill rate
// (tokens per second). The bucket starts full.
func New(burst int, rate float64, clock Clock) (*Limiter, error) {
	if burst <= 0 {
		return nil, errors.New("ratelimit: burst must be positive")
	}
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be positive")
	}
	if clock == nil {
		clock = RealClock()
	}
	return &Limiter{
		tokens: float64(burst),
		last:   clock.Now(),
		burst:  burst,
		rate:   rate,
		clock:  clock,
	}, nil
}

// Allow reports whether one token is available at the current time.
func (l *Limiter) Allow() bool { return l.AllowN(time.Time{}, 1) }

// AllowN reports whether n tokens are available. If now is the zero time,
// the limiter's clock is used; otherwise now is treated as the current time
// (useful for deterministic testing).
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if now.IsZero() {
		now = l.clock.Now()
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens = min(float64(l.burst), l.tokens+elapsed*l.rate)
		l.last = now
	}
	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// RetryAfter returns the duration until n tokens would be available,
// or 0 if they are available now.
func (l *Limiter) RetryAfter(now time.Time, n int) time.Duration {
	if now.IsZero() {
		now = l.clock.Now()
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens = min(float64(l.burst), l.tokens+elapsed*l.rate)
		l.last = now
	}
	if float64(n) <= l.tokens {
		return 0
	}
	need := float64(n) - l.tokens
	return time.Duration(need / l.rate * float64(time.Second))
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
