package ratelimit

import (
	"sync"
	"testing"
	"time"
)

type fakeClock struct {
	mu sync.Mutex
	t  time.Time
}

func newFakeClock(t time.Time) *fakeClock { return &fakeClock{t: t} }

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.t
}

func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.t = c.t.Add(d)
}

func TestNewValidation(t *testing.T) {
	tests := []struct {
		name    string
		burst   int
		rate    float64
		wantErr bool
	}{
		{"ok", 1, 1, false},
		{"zero burst", 0, 1, true},
		{"negative burst", -1, 1, true},
		{"zero rate", 1, 0, true},
		{"negative rate", 1, -0.5, true},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			_, err := New(tc.burst, tc.rate, newFakeClock(time.Unix(0, 0)))
			if (err != nil) != tc.wantErr {
				t.Fatalf("New(%d, %v) err = %v, wantErr %v", tc.burst, tc.rate, err, tc.wantErr)
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	base := time.Unix(0, 0)
	tests := []struct {
		name  string
		burst int
		rate  float64
		steps []struct {
			advance time.Duration
			n       int
			want    bool
		}
	}{
		{
			name:  "burst exhausted then refills",
			burst: 2, rate: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 2, true},   // full bucket
				{0, 1, false},  // empty
				{time.Second, 1, true},  // 1 token refilled
				{time.Second, 2, false}, // only 1 available
				{time.Second, 2, true},  // now 2 available
			},
		},
		{
			name:  "fractional refill accumulates",
			burst: 1, rate: 2,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 1, true},
				{0, 1, false},
				{300 * time.Millisecond, 1, false}, // 0.6 tokens
				{200 * time.Millisecond, 1, true},  // 1.0 tokens
			},
		},
		{
			name:  "cap at burst",
			burst: 3, rate: 10,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 3, true},
				{time.Hour, 3, true}, // capped, not 603
				{0, 1, false},
			},
		},
		{
			name:  "zero n always allowed",
			burst: 1, rate: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 1, true},
				{0, 0, true},
				{0, 1, false},
			},
		},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			clk := newFakeClock(base)
			l, err := New(tc.burst, tc.rate, clk)
			if err != nil {
				t.Fatal(err)
			}
			for i, s := range tc.steps {
				clk.Advance(s.advance)
				if got := l.AllowN(time.Time{}, s.n); got != s.want {
					t.Errorf("step %d: AllowN(%d) = %v, want %v", i, s.n, got, s.want)
				}
			}
		})
	}
}

func TestAllowNExplicitTime(t *testing.T) {
	clk := newFakeClock(time.Unix(0, 0))
	l, _ := New(1, 1, clk)
	if !l.AllowN(time.Unix(0, 0), 1) {
		t.Fatal("first AllowN should succeed")
	}
	// Explicit future time bypasses the fake clock.
	if !l.AllowN(time.Unix(1, 0), 1) {
		t.Fatal("AllowN at t+1s should succeed")
	}
}

func TestRetryAfter(t *testing.T) {
	clk := newFakeClock(time.Unix(0, 0))
	l, _ := New(1, 2, clk) // 2 tokens/sec
	l.AllowN(time.Time{}, 1)
	if got := l.RetryAfter(time.Time{}, 1); got != 500*time.Millisecond {
		t.Errorf("RetryAfter = %v, want 500ms", got)
	}
}

func TestConcurrent(t *testing.T) {
	clk := newFakeClock(time.Unix(0, 0))
	l, _ := New(100, 1000, clk)
	var wg sync.WaitGroup
	var allowed int64
	var mu sync.Mutex
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if l.Allow() {
				mu.Lock()
				allowed++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	if allowed != 100 {
		t.Errorf("allowed = %d, want 100 (burst)", allowed)
	}
}
